//! Verify the wasm bridge exports the plan §8.4 names plus T-038 helpers.
//!
//! wasm-bindgen appends a crate hash to each raw export (`cb_tick_ab12...`);
//! the public JS names without the suffix are generated by the wasm-bindgen
//! CLI at deploy time. This script checks the part that is true of the raw
//! module: exactly the contracted `cb_` exports, one for each base name,
//! with an optional hash suffix and nothing extra.
//!
//! Usage: node tools/wasm-exports.mjs target/wasm32-unknown-unknown/release/client_wasm.wasm

import fs from "node:fs";

const CONTRACT = [
  "cb_protocol_version",
  "cb_init",
  "cb_tick",
  "cb_on_snapshot",
  "cb_local_edit",
  "cb_ack_edit",
  "cb_dirty_chunks",
  "cb_mesh_chunk",
  "cb_release_mesh",
  "cb_render_desc",
  "cb_set_quality",
  "cb_state_hash",
  "cb_mem_alloc",
  "cb_recipes",
  "cb_near_miss",
  "cb_offline_init",
  "cb_offline_message",
  "cb_offline_tick",
  "cb_offline_poll",
  "cb_offline_state_hash",
];

const path = process.argv[2];
if (!path) {
  console.error("usage: node tools/wasm-exports.mjs <client_wasm.wasm>");
  process.exit(2);
}

const module = new WebAssembly.Module(fs.readFileSync(path));
const exported = WebAssembly.Module.exports(module)
  .filter((entry) => entry.kind === "function" && entry.name.startsWith("cb_"))
  .map((entry) => entry.name);

const seen = new Map();
for (const name of exported) {
  const match = /^(cb_.+?)(?:_[0-9a-f]{16})?$/.exec(name);
  const base = match ? match[1] : name;
  seen.set(base, (seen.get(base) ?? 0) + 1);
}

const missing = CONTRACT.filter((name) => !seen.has(name));
const extra = [...seen.keys()].filter((name) => !CONTRACT.includes(name));
const duplicated = [...seen.entries()].filter(([, count]) => count !== 1);

if (missing.length > 0 || extra.length > 0 || duplicated.length > 0) {
  console.error("wasm export contract violated");
  if (missing.length > 0) console.error("  missing:", missing);
  if (extra.length > 0) console.error("  extra:", extra);
  if (duplicated.length > 0) console.error("  duplicated:", duplicated);
  process.exit(1);
}

console.log(`wasm exports ok: ${CONTRACT.length} functions`);
